function Invoke-RecipeManagementSmokeTests { param([string]$Username="",[string]$Password="")
    if(-not$Username-or-not$Password){Write-TestSkipped "Recipe management tests";Write-TestSkipped "Recipe thumbnail tests";return};$login=Invoke-ApiRequest "POST" "/api/v1/auth/login" -Body @{username=$Username;password=$Password};if($login.StatusCode-ne 200){Write-TestSkipped "Recipe management tests";Write-TestSkipped "Recipe thumbnail tests";return};$headers=@{Authorization="Bearer $((Convert-JsonResponse $login 'Recipe management login contains valid JSON').token)"};$categories=Invoke-ApiRequest "GET" "/api/v1/categories";$categoryId=(Convert-JsonResponse $categories "Recipe category list contains valid JSON").data[0].id;if(-not$categoryId){Write-TestFailure "Recipe management requires an existing category";return};$suffix=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$id=$null;$imagePath=[System.IO.Path]::GetTempFileName()+".png"
    try{$r=Invoke-ApiRequest "POST" "/api/v1/recipes" -Headers $headers -Body @{title="Smoke recipe $suffix";content="Temporary smoke test recipe content.";duration=15;categoryId=$categoryId;visibility="private"};if(-not(Assert-StatusCode $r 201 "Creator can create a recipe")){return};$d=Convert-JsonResponse $r "Created recipe contains valid JSON";$id=$d.data.id;if($id-and$d.data.visibility-eq"private"){Write-TestSuccess "Created recipe follows the V1 contract"}else{Write-TestFailure "Created recipe follows the V1 contract";return};$categorySlug=(Convert-JsonResponse $categories "Recipe category list contains valid JSON").data[0].slug;$mine=Invoke-ApiRequest "GET" "/api/v1/me/recipes?visibility=private&category=$categorySlug&q=Smoke" -Headers $headers;if(Assert-StatusCode $mine 200 "Creator can list own recipes"){if(@((Convert-JsonResponse $mine "Own recipes response contains valid JSON").data|Where-Object{$_.id-eq$id}).Count-eq 1){Write-TestSuccess "Private recipe appears in its creator listing"}else{Write-TestFailure "Private recipe appears in its creator listing"}};$r=Invoke-ApiRequest "PATCH" "/api/v1/recipes/$id" -Headers $headers -Body @{title="Updated smoke recipe $suffix";visibility="public"};if(Assert-StatusCode $r 200 "Owner can update a recipe"){if((Convert-JsonResponse $r "Updated recipe contains valid JSON").data.visibility-eq"public"){Write-TestSuccess "Updated recipe contains the new visibility"}else{Write-TestFailure "Updated recipe contains the new visibility"}};[System.IO.File]::WriteAllBytes($imagePath,[Convert]::FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII="));$r=Invoke-ApiMultipartRequest "/api/v1/recipes/$id/thumbnail" $imagePath $headers;if(Assert-StatusCode $r 200 "Owner can upload a recipe thumbnail"){if((Convert-JsonResponse $r "Thumbnail response contains valid JSON").data.thumbnailUrl){Write-TestSuccess "Thumbnail response contains its URL"}else{Write-TestFailure "Thumbnail response contains its URL"}};$r=Invoke-ApiRequest "DELETE" "/api/v1/recipes/$id/thumbnail" -Headers $headers;if(Assert-StatusCode $r 204 "Owner can delete a recipe thumbnail"){};$r=Invoke-ApiRequest "DELETE" "/api/v1/recipes/$id" -Headers $headers;if(Assert-StatusCode $r 204 "Owner can delete a recipe"){$id=$null}}finally{if($null-ne$id){$null=Invoke-ApiRequest "DELETE" "/api/v1/recipes/$id" -Headers $headers};if(Test-Path $imagePath){Remove-Item -LiteralPath $imagePath -Force}}
}
